class TrustedSendersCompanion extends UpdateCompanion<TrustedSendersData> {
  final Value<String> sender;
  final Value<int> trusted;
  final Value<int> createdAt;
  final Value<int> rowid;
  const TrustedSendersCompanion({
    this.sender = const Value.absent(),
    this.trusted = const Value.absent(),
    this.createdAt = const Value.absent(),
    this.rowid = const Value.absent(),
  });
  TrustedSendersCompanion.insert({
    required String sender,
    required int trusted,
    this.createdAt = const Value.absent(),
    this.rowid = const Value.absent(),
  }) : sender = Value(sender),
       trusted = Value(trusted);
  static Insertable<TrustedSendersData> custom({
    Expression<String>? sender,
    Expression<int>? trusted,
    Expression<int>? createdAt,
    Expression<int>? rowid,
  }) {
    return RawValuesInsertable({
      if (sender != null) 'sender': sender,
      if (trusted != null) 'trusted': trusted,
      if (createdAt != null) 'created_at': createdAt,
      if (rowid != null) 'rowid': rowid,
    });
  }

  TrustedSendersCompanion copyWith({
    Value<String>? sender,
    Value<int>? trusted,
    Value<int>? createdAt,
    Value<int>? rowid,
  }) {
    return TrustedSendersCompanion(
      sender: sender ?? this.sender,
      trusted: trusted ?? this.trusted,
      createdAt: createdAt ?? this.createdAt,
      rowid: rowid ?? this.rowid,
    );
  }

  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    if (sender.present) {
      map['sender'] = Variable<String>(sender.value);
    }
    if (trusted.present) {
      map['trusted'] = Variable<int>(trusted.value);
    }
    if (createdAt.present) {
      map['created_at'] = Variable<int>(createdAt.value);
    }
    if (rowid.present) {
      map['rowid'] = Variable<int>(rowid.value);
    }
    return map;
  }

  @override
  String toString() {
    return (StringBuffer('TrustedSendersCompanion(')
          ..write('sender: $sender, ')
          ..write('trusted: $trusted, ')
          ..write('createdAt: $createdAt, ')
          ..write('rowid: $rowid')
          ..write(')'))
        .toString();
  }
}

